class Graph:
    def __init__(self, graph_dict=None, directed=True):
        self.graph_dict = graph_dict or {}
        self.directed = directed
        if not directed:
            self.make_undirected()

    def make_undirected(self):
        for a in list(self.graph_dict.keys()):
            for (b, dist) in self.graph_dict[a].items():
                self.graph_dict.setdefault(b, {})[a] = dist

    def add_vertex(self, vertex):
        if vertex not in self.graph_dict:
            self.graph_dict[vertex] = {}

    def add_edge(self, start_vertex, end_vertex, distance=1):
        self.graph_dict[start_vertex][end_vertex] = distance
        if not self.directed:
            self.graph_dict[end_vertex][start_vertex] = distance

    def remove_edge(self, start_vertex, end_vertex):
        if end_vertex in self.graph_dict[start_vertex]:
            del self.graph_dict[start_vertex][end_vertex]
            if not self.directed:
                del self.graph_dict[end_vertex][start_vertex]

    def remove_vertex(self, vertex):
        if vertex in self.graph_dict:
            del self.graph_dict[vertex]
            for v in self.graph_dict:
                if vertex in self.graph_dict[v]:
                    del self.graph_dict[v][vertex]

    def path_exists(self, start_vertex, end_vertex):
        """
        Returns True if a path exists from start_vertex to end_vertex
        """
        visited = set()
        return self.dfs(start_vertex, end_vertex, visited)

    def dfs(self, start_vertex, end_vertex, visited=None):
        if visited is None:
            visited = set()
        visited.add(start_vertex)
        if start_vertex == end_vertex:
            return True
        for next_vertex in self.graph_dict[start_vertex]:
            if next_vertex not in visited:
                if self.dfs(next_vertex, end_vertex, visited):
                    return True
        return False

def dfs_path_search(graph, start, goal):
    if graph.path_exists(start, goal):
        return graph.dfs(start, goal)
    else:
        return False

