        self.directed = directed
        if not directed:
            self.make_undirected()

    def make_undirected(self):
        for a in list(self.graph_dict.keys()):
            for (b, dist) in self.graph_dict[a].items():
                self.graph_dict.setdefault(b, {})[a] = dist

    def connect(self, A, B, distance=1):
        self.graph_dict.setdefault(A, {})[B] = distance
        if not self.directed:
            self.graph_dict.setdefault(B, {})[A] = distance

    def get(self, a, b=None):
        links = self.graph_dict.get(a)
        if b is None:
            return links
        else:
            return links.get(b)

    def nodes(self):
        return list(self.graph_dict.keys())

def bfs(graph, start, goal):
    if goal not in graph.nodes():
        raise ValueError('Invalid goal node')

    # Keep track of visited nodes
    visited = []

    # Keep track of nodes to be checked
    queue = [[start]]

    # If the desired node is the start node, just yield it.
    if start == goal:
        yield [start]
        return

    while queue:
        # Create a new list to hold the next level of nodes to check
        path = queue.pop(0)

        # Get the last node from the path
        node = path[-1]

        # If we have not yet visited this node
        if node not in visited:
            neighbors = graph.get(node)

            for neighbor in neighbors:
                # Create a new path and add it to the queue
                new_path = list(path)
                new_path.append(neighbor)
                queue.append(new_path)

                # If we have reached the goal node, yield the path
                if neighbor == goal:
                    yield new_path

            # Mark node as visited
            visited.append(node)

